package dev.raven.backup;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.*;import android.provider.DocumentsContract;import org.json.*;import java.io.*;import java.util.*;
public class SpecialFilesRestoreTest extends Instrumentation{
 void require(boolean v,String m){if(!v)throw new AssertionError(m);}public void onCreate(Bundle b){super.onCreate(b);start();}
 void probe(BackupEngine e,boolean changed)throws Exception{String pkg=SetupCheck.PACKAGE,path="/data/user/0/"+pkg+"/cache/special-report.json";e.run(e.job(),"am force-stop --user 0 "+BackupEngine.q(pkg)+"\nrm -f -- "+BackupEngine.q(path)+"\nam start -W --user 0 -n "+BackupEngine.q(pkg+"/dev.raven.backupfixture.Seed")+" --es mode verify-special"+(changed?" --es expect mutated":"")+"\nn=0; while [ ! -f "+BackupEngine.q(path)+" ]; do n=$((n+1)); [ \"$n\" -lt 40 ]; sleep 0.25; done\ngrep -q '\"success\":true' "+BackupEngine.q(path)+"\ncat "+BackupEngine.q(path)+"\n",false);}
 public void onStart(){Bundle report=new Bundle();try{Context c=getTargetContext();startActivitySync(new Intent(c,MainActivity.class).addFlags(Intent.FLAG_ACTIVITY_NEW_TASK));require(!OperationService.running()&&!new LiveRestore(c).pointer.exists(),"operation/pending restore");report.putString("setup",SetupCheck.run(c));BackupEngine e=new BackupEngine(c);File own=e.job(),apk=new File(own,"helper.apk");Uri folder=null;String pkg=SetupCheck.PACKAGE;
  try{try(InputStream in=c.getAssets().open("restore-check.apk");OutputStream out=new FileOutputStream(apk)){BackupEngine.copy(in,out,16*1024*1024);}e.run(e.job(),"pm install --user 0 "+BackupEngine.q(apk.getPath())+"\n",false);SetupCheck.mode(e,"seed");
   String name="NOVA_"+new String(new char[130]).replace('\0','o')+".obb",base="/data/user/0/"+pkg,media="/data/media/0/Android/data/"+pkg+"/files",target="/storage/emulated/0/Android/data/"+pkg+"/files/"+name,link=base+"/files/linked.obb",newline=base+"/shared_prefs/name\n.xml",fifo=base+"/files/audio.pcm";int uid=e.info(pkg).getInt("uid");String security=RootBridge.call("ls -Zd "+BackupEngine.q(base)).trim().split("\\s+")[0];
   e.run(e.job(),"mkdir -p "+BackupEngine.q(media)+"\nprintf '%s' 'original external bytes' > "+BackupEngine.q(media+"/"+name)+"\nmkfifo "+BackupEngine.q(fifo)+"\nchmod 640 "+BackupEngine.q(fifo)+"\nln -s -- "+BackupEngine.q(target)+" "+BackupEngine.q(link)+"\nprintf '%s' '<map>original</map>' > "+BackupEngine.q(newline)+"\nchown -h "+uid+":"+uid+" "+BackupEngine.q(link)+" "+BackupEngine.q(newline)+" "+BackupEngine.q(fifo)+"\nchmod 640 "+BackupEngine.q(newline)+"\nchcon -h "+BackupEngine.q(security)+" "+BackupEngine.q(link)+" "+BackupEngine.q(newline)+" "+BackupEngine.q(fifo)+"\n",false);probe(e,false);
   Uri tree=SetupActivity.folder(c);folder=DocumentsContract.createDocument(c.getContentResolver(),DocumentsContract.buildDocumentUriUsingTree(tree,DocumentsContract.getTreeDocumentId(tree)),DocumentsContract.Document.MIME_TYPE_DIR,"Raven-special-files-disposable-"+UUID.randomUUID());e.backupApks=true;e.backupExternal=true;e.backupOne(Collections.singletonList(pkg),tree,folder);Uri original=e.lastBackupUri;
   SetupCheck.mode(e,"mutate");e.run(e.job(),"chmod 600 "+BackupEngine.q(fifo)+"\nprintf '%s' 'changed external bytes' > "+BackupEngine.q(media+"/"+name)+"\nprintf '%s' '<map>changed</map>' > "+BackupEngine.q(newline)+"\n",false);probe(e,true);
   LiveRestore live=new LiveRestore(c);live.testing=true;live.keepRollback=false;String failed=live.restoreInternal(live.prepare(original),true);require(failed.startsWith("Restore failed and rollback verified"),"rollback failed");probe(e,true);report.putString("rollback","PASS pre-existing scoped symlink/newline file survived controlled restore failure, independently read by app");
   String success=live.restore(live.prepare(original),false,false);require(success.startsWith("Restored "),success);live.verifyLaunch(Collections.singletonList(pkg),false);probe(e,false);report.putString("restore",success+" Independent helper read through restored long-target symbolic link and newline preference filename passed.");
   e.run(e.job(),"mv -- "+BackupEngine.q(media+"/"+name)+" "+BackupEngine.q(media+"/other-file")+"\n",false);e.backupOne(Collections.singletonList(pkg),tree,folder);Uri missing=e.lastBackupUri;boolean refused=false;try{live.restore(live.prepare(missing),false,false);}catch(IOException expected){refused=expected.getMessage().contains("missing from the staged external backup");}require(refused&&!live.pointer.exists(),"missing link target accepted/pending");e.run(e.job(),"mv -- "+BackupEngine.q(media+"/other-file")+" "+BackupEngine.q(media+"/"+name)+"\n",false);probe(e,false);report.putString("missing_target","PASS incomplete external backup refused before private replacement; previous data unchanged");
  }finally{if(!new LiveRestore(c).pointer.exists()){if(SetupCheck.installed(e))e.run(e.job(),"pm uninstall "+BackupEngine.q(pkg)+"\n",false);if(folder!=null)DocumentsContract.deleteDocument(c.getContentResolver(),folder);e.clean(own);}}
  report.putString("result","PASS");finish(-1,report);
 }catch(Throwable t){report.putString("error",android.util.Log.getStackTraceString(t));finish(0,report);}}
}
